// === Tab: ZenWaterfallGarden ===
/*
  AAA ZEN WATERFALL GARDEN v1.0 — p5.js / OpenProcessing // "Waterfall" 🚿 #WCCChallenge
  subtle credit: Rodrigo Reyes ( @_ixtam_ )

  CLICK/TAP:
  - Activa audio
  - Click en cascada: gota musical + ripple
  - Mantener click dentro de cascada: más gotas reales caen hacia esa zona
  - Click en pez: sonido armónico + pez nada rápido
  - Click en loto / hongo / piedra: interacción zen

  KEYS:
  R = nueva escena procedural
  S = guardar imagen
  M = mute/unmute
  B = respiración zen
  L = luciérnagas extra
  W = intensidad de agua
  1 / 2 / 3 = mood de color
*/

let seed = 1;

let W, H, cx, cy, su;
let t = 0;
let breath = 0;

let bgLayer;

let drops = [];
let mushrooms = [];
let ripples = [];
let fireflies = [];
let koi = [];
let lotus = [];
let zenStones = [];
let fallingLeaves = [];
let glowSeeds = [];

let mouseField = 0;
let lastMx = 0;
let lastMy = 0;
let mouseSpeed = 0;
let lastFlowNoteFrame = 0;

let biome = {};

let audioStarted = false;
let muted = false;
let audioCtx;
let masterGain;
let waterGain;
let waterFilter;
let noiseSource;
let delayNode;
let flowPadGain;
let flowOscA;
let flowOscB;
let flowFilter;
let flowPanner;

let zenBreathBoost = false;
let fireflyBoost = false;
let waterBoost = false;
let moodOverride = -1;

const DROP_COUNT_DESKTOP = 370;
const DROP_COUNT_MOBILE = 225;
const FIREFLY_DESKTOP = 48;
const FIREFLY_MOBILE = 26;
const MAX_RIPPLES = 30;

function setup() {
  createCanvas(windowWidth, windowHeight);
  pixelDensity(1);
  frameRate(60);
  colorMode(HSB, 360, 100, 100, 100);
  textFont("monospace");
  textAlign(CENTER, CENTER);

  seed = floor(random(999999));
  resetSketch();
}

function resetSketch() {
  randomSeed(seed);
  noiseSeed(seed);

  W = width;
  H = height;
  cx = W * 0.5;
  cy = H * 0.5;
  su = min(W, H);

  drops = [];
  mushrooms = [];
  ripples = [];
  fireflies = [];
  koi = [];
  lotus = [];
  zenStones = [];
  fallingLeaves = [];
  glowSeeds = [];

  createBiome();
  createZenStones();
  createMushrooms();
  createLotus();
  createKoi();
  createDrops();
  createFireflies();
  createFallingLeaves();
  createGlowSeeds();
  renderBackground();

  background(biome.bgHue, 34, 9);
}

function draw() {
  t = frameCount * 0.012;
  breath = 0.5 + 0.5 * sin(t * (zenBreathBoost ? 0.9 : 0.62));

  W = width;
  H = height;
  cx = W * 0.5;
  cy = H * 0.5;
  su = min(W, H);

  let mvx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - lastMx;
  let mvy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - lastMy;
  lastMx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  lastMy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

  mouseSpeed = lerp(mouseSpeed, sqrt(mvx * mvx + mvy * mvy), 0.12);

  let insideFall = isInsideWaterfall((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  mouseField = lerp(
    mouseField,
    insideFall ? constrain(mouseSpeed / 42, 0.05, 0.75) : 0,
    0.075
  );

  if (insideFall && mouseSpeed > 7 && frameCount - lastFlowNoteFrame > 20) {
    playFlowNote((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), mouseSpeed);
    lastFlowNoteFrame = frameCount;
  }

  updateAudio();

  noStroke();
  fill(biome.bgHue, 34, 9, 14);
  rect(0, 0, W, H);

  image(bgLayer, 0, 0);

  drawAtmosphere();
  drawSunMistHalo();
  drawBackWaterSheets();
  drawMainWaterVolume();
  drawPoolSurface();
  drawZenStones();
  updateKoi();
  updateLotus();
  updateDrops();
  drawMushrooms();
  updateRipples();
  updateFireflies();
  updateFallingLeaves();
  updateGlowSeeds();
  drawFloatingPollen();
  drawForegroundLeaves();
  drawHeldWaterTarget();
  drawHUD();
}

/* BIOME */

function createBiome() {
  let mood = moodOverride >= 0 ? moodOverride : floor(random(4));

  let moods = [
    { bgHue: 202, waterHue: 188, leafHue: 112, warmHue: 42 },
    { bgHue: 196, waterHue: 184, leafHue: 104, warmHue: 36 },
    { bgHue: 210, waterHue: 192, leafHue: 122, warmHue: 48 },
    { bgHue: 188, waterHue: 180, leafHue: 96, warmHue: 32 }
  ];

  biome = moods[mood];

  biome.fallX = cx + random(-W * 0.018, W * 0.018);
  biome.fallTopW = W * random(0.13, 0.165);
  biome.fallBottomW = W * random(0.37, 0.45);
  biome.poolY = H * random(0.84, 0.87);
  biome.leftGarden = random(0.92, 1.08);
  biome.rightGarden = random(0.92, 1.08);
  biome.bambooDensity = floor(random(14, 22));
  biome.mistAmount = random(0.8, 1.15);
}

/* BACKGROUND */

function renderBackground() {
  bgLayer = createGraphics(W, H);
  bgLayer.pixelDensity(1);
  bgLayer.colorMode(HSB, 360, 100, 100, 100);

  bgLayer.background(biome.bgHue, 38, 8);

  for (let y = 0; y < H; y += 2) {
    let p = y / H;
    bgLayer.noStroke();
    bgLayer.fill(biome.bgHue - p * 14, 32 - p * 6, 10 + p * 13, 100);
    bgLayer.rect(0, y, W, 3);
  }

  drawMountainLayer(bgLayer, 0.14, 0.055, biome.bgHue - 5, 18, 17, 25);
  drawMountainLayer(bgLayer, 0.3, 0.085, biome.bgHue - 8, 24, 11, 36);
  drawMountainLayer(bgLayer, 0.49, 0.12, biome.bgHue - 12, 30, 8, 48);

  drawCliffWalls(bgLayer);
  drawStaticMist(bgLayer);
  drawBambooSilhouettes(bgLayer);
}

function drawMountainLayer(g, base, amp, h, s, b, a) {
  g.noStroke();
  g.fill(h, s, b, a);
  g.beginShape();
  g.vertex(0, H);

  for (let x = 0; x <= W; x += 20) {
    let n = noise(x * 0.004, base * 9, seed * 0.01);
    let y = H * base + n * H * amp + sin(x * 0.01 + base * 20) * H * amp * 0.22;
    g.vertex(x, y);
  }

  g.vertex(W, H);
  g.endShape(CLOSE);
}

function drawCliffWalls(g) {
  let gapTop = W * 0.28;
  let gapBottom = W * 0.48;

  g.noStroke();
  g.fill(biome.bgHue - 6, 32, 7, 78);

  g.beginShape();
  g.vertex(0, 0);
  g.vertex(biome.fallX - gapTop * 0.62, 0);
  g.vertex(biome.fallX - gapBottom * 0.52, H);
  g.vertex(0, H);
  g.endShape(CLOSE);

  g.beginShape();
  g.vertex(W, 0);
  g.vertex(biome.fallX + gapTop * 0.62, 0);
  g.vertex(biome.fallX + gapBottom * 0.52, H);
  g.vertex(W, H);
  g.endShape(CLOSE);

  g.strokeWeight(1);

  for (let i = 0; i < 46; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let x = side < 0 ? random(W * 0.03, W * 0.32) : random(W * 0.68, W * 0.97);
    var y = random(H * 0.03, H * 0.95);
    let len = random(35, 145);
    let a = side < 0 ? random(-0.18, 0.58) : random(PI - 0.58, PI + 0.18);

    g.stroke(170, 18, 52, random(4, 11));
    g.line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
}

function drawStaticMist(g) {
  g.noStroke();

  let count = floor(210 * biome.mistAmount);

  for (let i = 0; i < count; i++) {
    var x = biome.fallX + randomGaussian() * W * 0.22;
    var y = random(H * 0.22, H * 0.96);
    let r = random(0.8, 2.5);
    g.fill(biome.waterHue, 8, 100, random(1.5, 7));
    g.circle(x, y, r);
  }
}

function drawBambooSilhouettes(g) {
  g.strokeWeight(2);

  for (let i = 0; i < biome.bambooDensity; i++) {
    var side = i % 2 === 0 ? -1 : 1;
    var x = side < 0 ? random(W * 0.01, W * 0.17) : random(W * 0.83, W * 0.99);
    let y0 = H * random(0.16, 0.78);
    var len = H * random(0.22, 0.55);
    let bend = random(-14, 14);

    g.stroke(biome.leafHue, 30, 18, random(15, 28));
    g.noFill();
    g.beginShape();

    for (let j = 0; j <= 8; j++) {
      var p = j / 8;
      g.vertex(x + sin(p * PI) * bend, y0 + p * len);
    }

    g.endShape();

    for (let j = 0; j < 3; j++) {
      let yy = y0 + len * random(0.15, 0.9);
      let dir = random([-1, 1]);
      g.stroke(biome.leafHue + 4, 28, 24, random(8, 20));
      g.line(x, yy, x + dir * random(18, 42), yy - random(6, 24));
    }
  }
}

/* CREATION */

function createZenStones() {
  var count = W < 700 ? 5 : 8;

  for (let i = 0; i < count; i++) {
    var side = i % 2 === 0 ? -1 : 1;
    let gardenScale = side < 0 ? biome.leftGarden : biome.rightGarden;

    var x = biome.fallX + side * random(W * 0.16, W * 0.37) * gardenScale + random(-12, 12);
    var y = H * random(0.79, 0.955);

    zenStones.push({
      x,
      y,
      w: random(42, 90),
      h: random(16, 36),
      hue: random(188, 204),
      moss: random(0.3, 1),
      phase: random(TAU),
      hit: 0
    });
  }
}

function createMushrooms() {
  var count = W < 700 ? 7 : 11;

  for (let i = 0; i < count; i++) {
    let sideSpread = map(i, 0, count - 1, -1, 1);
    var x = biome.fallX + sideSpread * W * random(0.17, 0.39) + random(-16, 16);
    var y = H * random(0.755, 0.91);
    let scale = random(0.52, 1.16) * (1 - abs(sideSpread) * 0.22);

    mushrooms.push({
      x,
      y,
      s: scale,
      capHue: random([30, 34, 38, 42]),
      stemHue: random(35, 48),
      note: random([0, 2, 5, 7, 9, 12]),
      hit: 0,
      bloom: 0,
      phase: random(TAU)
    });
  }
}

function createLotus() {
  var count = W < 700 ? 5 : 8;

  for (let i = 0; i < count; i++) {
    var side = i % 2 === 0 ? -1 : 1;

    lotus.push({
      baseX: biome.fallX + side * random(W * 0.08, W * 0.35),
      x: 0,
      y: H * random(0.845, 0.97),
      s: random(0.52, 1.12),
      phase: random(TAU),
      hue: random([112, 118, 126, 132]),
      bloom: random(0.15, 0.5),
      drift: random(8, 24),
      speed: random(0.22, 0.48)
    });
  }

  for (let l of lotus) l.x = l.baseX;
}

function createKoi() {
  var count = W < 700 ? 3 : 5;

  for (let i = 0; i < count; i++) {
    koi.push({
      x: biome.fallX + random(-W * 0.34, W * 0.34),
      y: H * random(0.865, 0.965),
      laneY: 0,
      vx: random([-1, 1]) * random(0.22, 0.56),
      s: random(0.62, 1.12),
      hue: random([22, 30, 38, 44]),
      phase: random(TAU),
      panic: 0,
      happy: 0
    });
  }

  for (let k of koi) k.laneY = k.y;
}

function createDrops() {
  var count = W < 700 ? DROP_COUNT_MOBILE : DROP_COUNT_DESKTOP;
  for (let i = 0; i < count; i++) drops.push(new Drop(i));
}

function createFireflies() {
  var count = W < 700 ? FIREFLY_MOBILE : FIREFLY_DESKTOP;

  for (let i = 0; i < count; i++) {
    fireflies.push({
      x: random(W),
      y: random(H * 0.18, H * 0.75),
      vx: random(-0.15, 0.15),
      vy: random(-0.1, 0.1),
      r: random(1.0, 2.4),
      p: random(TAU)
    });
  }
}

function createFallingLeaves() {
  var count = W < 700 ? 12 : 22;

  for (let i = 0; i < count; i++) {
    fallingLeaves.push({
      x: random(W),
      y: random(-H, H),
      s: random(0.6, 1.5),
      vx: random(-0.28, 0.28),
      vy: random(0.18, 0.58),
      a: random(TAU),
      phase: random(TAU),
      hue: biome.leafHue + random(-8, 14)
    });
  }
}

function createGlowSeeds() {
  var count = W < 700 ? 18 : 30;

  for (let i = 0; i < count; i++) {
    glowSeeds.push({
      x: random(W),
      y: random(H * 0.15, H * 0.78),
      phase: random(TAU),
      r: random(0.6, 1.6),
      drift: random(0.2, 0.7)
    });
  }
}

/* ART LAYERS */

function drawAtmosphere() {
  push();
  blendMode(ADD);
  noStroke();

  let boost = zenBreathBoost ? 1.45 : 1;

  for (let i = 0; i < 5; i++) {
    var p = i / 4;
    fill(biome.waterHue, 20, 100, (1.8 + breath * 1.0) * boost);
    ellipse(
      biome.fallX,
      H * (0.38 + p * 0.08),
      W * (0.3 + p * 0.23),
      H * (0.68 + p * 0.15)
    );
  }

  blendMode(BLEND);
  pop();
}

function drawSunMistHalo() {
  push();
  blendMode(ADD);
  noStroke();

  var x = biome.fallX - W * 0.12;
  var y = H * 0.22;
  var r = su * (0.25 + breath * 0.03);

  for (let i = 8; i > 0; i--) {
    var p = i / 8;
    fill(biome.warmHue, 24, 95, 1.15);
    ellipse(x, y, r * p * 2.1, r * p * 1.45);
  }

  blendMode(BLEND);
  pop();
}

function drawBackWaterSheets() {
  push();
  blendMode(ADD);
  noFill();

  let sheets = W < 700 ? 5 : 8;

  for (let i = 0; i < sheets; i++) {
    let u = map(i, 0, sheets - 1, -1, 1);
    let alpha = 6 + (1 - abs(u)) * 12;

    stroke(biome.waterHue, 18, 95, alpha);
    strokeWeight(1.0 + (1 - abs(u)) * 2.0);

    beginShape();

    for (let y = -20; y <= H + 40; y += 20) {
      var p = y / H;
      let topW = biome.fallTopW * (0.9 + breath * 0.06);
      let bottomW = biome.fallBottomW * (0.82 + breath * 0.04);
      let fallW = lerp(topW, bottomW, p);

      let depthOffset = u * fallW * 0.5;
      let sway = sin(y * 0.014 + t * 1.8 + i) * (11 + breath * 3);
      var n = noise(i * 0.2, y * 0.006, t * 0.18);

      var x = biome.fallX + depthOffset + sway + (n - 0.5) * 26;
      vertex(x, y);
    }

    endShape();
  }

  blendMode(BLEND);
  pop();
}

function drawMainWaterVolume() {
  push();
  blendMode(ADD);
  noStroke();

  var boost = waterBoost ? 1.14 : 1;

  for (let i = 10; i > 0; i--) {
    var p = i / 10;
    var topW = biome.fallTopW * (0.55 + p * 0.72 + breath * 0.04) * boost;
    var bottomW = biome.fallBottomW * (0.56 + p * 0.52 + breath * 0.03) * boost;
    var alpha = 1.8 + p * 2.25;

    fill(biome.waterHue, 20, 96, alpha);

    beginShape();

    for (let y = -20; y <= H + 40; y += 24) {
      let q = y / H;
      let w = lerp(topW, bottomW, q);
      var x = biome.fallX - w * 0.5 + sin(y * 0.012 + t * 1.1) * 7 * p;
      vertex(x, y);
    }

    for (let y = H + 40; y >= -20; y -= 24) {
      var q = y / H;
      var w = lerp(topW, bottomW, q);
      var x = biome.fallX + w * 0.5 + sin(y * 0.011 + t * 1.0 + 3) * 7 * p;
      vertex(x, y);
    }

    endShape(CLOSE);
  }

  blendMode(BLEND);
  pop();
}

function drawPoolSurface() {
  push();
  blendMode(ADD);
  noFill();

  for (let i = 0; i < 8; i++) {
    var y = biome.poolY + i * 11;
    var w = W * (0.17 + i * 0.055);
    var a = 4.5 - i * 0.32;

    stroke(biome.waterHue, 18, 100, a);
    strokeWeight(1);

    beginShape();
    for (let x = biome.fallX - w; x <= biome.fallX + w; x += 20) {
      var yy = y + sin(x * 0.015 + t * 1.5 + i) * 2.2;
      vertex(x, yy);
    }
    endShape();
  }

  blendMode(BLEND);
  pop();
}

/* DROPS */

class Drop {
  constructor(id) {
    this.id = id;
    this.reset(true);
  }

  reset(anywhere) {
    var y = anywhere ? random(-60, H + 70) : random(-100, -10);
    var q = constrain(y / H, 0, 1);
    var fallW = lerp(biome.fallTopW, biome.fallBottomW, q);

    this.x = biome.fallX + randomGaussian() * fallW * 0.17;
    this.y = y;

    this.px = this.x;
    this.py = this.y;

    this.z = random(0.15, 1);
    this.vx = random(-0.12, 0.12);
    this.vy = random(3.0, 7.2) * lerp(0.72, 1.28, this.z);
    this.len = random(5, 20) * this.z;
    this.w = random(0.42, 1.22) * this.z;
    this.alpha = random(22, 60) * this.z;
    this.phase = random(TAU);
    this.cool = 0;
  }

  redirectToHeldWater() {
    var q = constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / H, 0, 1);
    let targetFallW = lerp(biome.fallTopW, biome.fallBottomW, q);

    this.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + randomGaussian() * targetFallW * 0.075;
    this.y = random(-100, -12);
    this.px = this.x;
    this.py = this.y;
    this.vx = random(-0.22, 0.22);
    this.vy = random(5.4, 9.8) * lerp(0.72, 1.2, this.z);
    this.alpha = random(32, 72) * this.z;
  }

  update() {
    this.px = this.x;
    this.py = this.y;

    var q = constrain(this.y / H, 0, 1);
    var fallW = lerp(biome.fallTopW, biome.fallBottomW, q);

    var n = noise(this.id * 0.035, this.y * 0.008, t * 0.28);
    let flow = (n - 0.5) * 0.65 + sin(this.y * 0.018 + t * 2.1 + this.phase) * 0.13;

    this.vx += flow * this.z;
    this.vx += (biome.fallX - this.x) * 0.0005;

    if (isInsideWaterfall((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))) {
      let d = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.x, this.y);
      let m = constrain(1 - d / (su * 0.23), 0, 1);
      var a = atan2(this.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));

      this.vx += cos(a) * m * (0.22 + mouseField * 0.85);
      this.vy += sin(a) * m * (0.04 + mouseField * 0.2);
    }

    this.x += this.vx;
